(function mergeRanges(ranges) {
    if (!Array.isArray(ranges)) {
        throw new TypeError('Input must be an array of ranges');
    }

    const result = [];

    for (const range of ranges) {
        if (!Array.isArray(range) || range.length !== 2) {
            throw new TypeError('Each range must be an array of exactly 2 numbers');
        }

        const start = Number(range[0]), end = Number(range[1]);
        if (!Number.isFinite(start) || !Number.isFinite(end)) {
            throw new TypeError("Range endpoints must be finite numbers");
        }
        if (start > end) {
            throw new TypeError('Range start must be <= end');
        }

        result.push({start, end}); // Store as objects for easier manipulation
    }

    // Sort ranges by start
    result.sort((a, b) => a.start - b.start);

    // Merge the result
    const merged = [];
    for (const r of result) {
        const {start, end} = r;
        const last = merged[merged.length - 1];

        if (last && last.end >= start) {
            // Ranges overlap or touch: merge
            last.end = Math.max(last.end, end);
        } else {
            // Disjoint: add as new
            merged.push({start, end});
        }
    }

    return merged.map(r => [r.start, r.end]);
})([]);

// Public API
export const protocolVersion = 1;
export const mergeRanges;

